param([Parameter(Mandatory=$true)][string]$InstallerUrl,[string]$OutFile="$env:RUNNER_TEMP\asc-probe.json")
$ErrorActionPreference='Stop';$tmp=Join-Path $env:RUNNER_TEMP 'asc-probe';New-Item -ItemType Directory -Force $tmp|Out-Null;$installer=Join-Path $tmp 'aScTimeTables.exe';Invoke-WebRequest -UseBasicParsing $InstallerUrl -OutFile $installer
$hash=(Get-FileHash $installer -Algorithm SHA256).Hash.ToLowerInvariant();$sig=Get-AuthenticodeSignature $installer;$fv=[Diagnostics.FileVersionInfo]::GetVersionInfo($installer)
$seven=(Get-Command 7z.exe -ErrorAction SilentlyContinue);$files=@();$exeMeta=@();if($seven){$extract=Join-Path $tmp 'extract';New-Item -ItemType Directory -Force $extract|Out-Null;& $seven.Source x '-y' "-o$extract" $installer *> (Join-Path $tmp '7z-extract.log');$files=Get-ChildItem $extract -Recurse -File|ForEach-Object{$_.FullName.Substring($extract.Length+1)};foreach($e in Get-ChildItem $extract -Recurse -File -Filter *.exe){$v=[Diagnostics.FileVersionInfo]::GetVersionInfo($e.FullName);$s=Get-AuthenticodeSignature $e.FullName;$exeMeta+=@{path=$e.FullName.Substring($extract.Length+1);file_version=$v.FileVersion;product_version=$v.ProductVersion;product_name=$v.ProductName;signature_status=[string]$s.Status;signer=if($s.SignerCertificate){$s.SignerCertificate.Subject}else{$null}}}}
$bytes=[IO.File]::ReadAllBytes($installer);$text=[Text.Encoding]::ASCII.GetString($bytes);$patterns=@('command line','--generate','/generate','-generate','--help','/help','automation','xml','\.roz');$hits=@{};foreach($p in $patterns){$m=[regex]::Matches($text,$p,[Text.RegularExpressions.RegexOptions]::IgnoreCase);$hits[$p]=[Math]::Min($m.Count,999)}
$r=[ordered]@{schema='OKULOS_ASC_EXECUTABLE_PROBE_V1';status='PROBED_NOT_GENERATED';download_url=$InstallerUrl;sha256=$hash;size_bytes=(Get-Item $installer).Length;installer=@{file_version=$fv.FileVersion;product_version=$fv.ProductVersion;product_name=$fv.ProductName;company_name=$fv.CompanyName;signature_status=[string]$sig.Status;signer=if($sig.SignerCertificate){$sig.SignerCertificate.Subject}else{$null}};extracted_file_count=$files.Count;extracted_executables=$exeMeta;ascii_surface_hits=$hits;generation_status='NOT_RUN';claim='Probe evidence only. No generation, objective parity, or performance claim.';runner=@{os=[Environment]::OSVersion.VersionString;processor=$env:PROCESSOR_IDENTIFIER}}
$r|ConvertTo-Json -Depth 8|Set-Content -Encoding utf8 $OutFile;Get-Content $OutFile